// ——— WhatsApp Cloud API message normalize ———
const body = $input.first().json.body || $input.first().json;

const change = body.entry?.[0]?.changes?.[0]?.value;
const msg = change?.messages?.[0];

// যদি message না থাকে (status update ইত্যাদি) → skip
if (!msg) {
  return [{ json: { skip: true } }];
}

const senderId = msg.from || '';
const phoneNumberId = change?.metadata?.phone_number_id || '';
const msgType = msg.type || 'text';

let messageText = '';
let imageId = '';
let hasImage = false;

if (msgType === 'text') {
  messageText = msg.text?.body || '';
} else if (msgType === 'image') {
  hasImage = true;
  imageId = msg.image?.id || '';
  messageText = msg.image?.caption || 'এই বইটির দাম কত?';
}

return [{
  json: {
    skip: false,
    senderId,
    phoneNumberId,
    msgType,
    messageText,
    imageId,
    hasImage,
    channel: 'whatsapp',
    timestamp: Date.now()
  }
}];

// বইয়ের ছবি থেকে চেনা title + sheet মিলিয়ে দাম বের করা
const visionRaw = $('Identify Book (Vision)').first().json;
const visionText = visionRaw.content || visionRaw.text || visionRaw.message?.content || JSON.stringify(visionRaw);

let identified = { title: '', author: '', keywords: '' };
try {
  const m = visionText.match(/\{[\s\S]*\}/);
  if (m) identified = JSON.parse(m[0]);
} catch (e) {}

const products = $('Read Product Sheet (for image)').all().map(r => r.json);

// ——— Fuzzy matching helper ———
function normalize(s) {
  return (s || '').toString().toLowerCase().replace(/[^a-z0-9\u0980-\u09FF ]/g, '').trim();
}
function score(a, b) {
  a = normalize(a); b = normalize(b);
  if (!a || !b) return 0;
  if (a === b) return 100;
  if (a.includes(b) || b.includes(a)) return 80;
  const wordsA = a.split(' ').filter(Boolean);
  const wordsB = b.split(' ').filter(Boolean);
  let common = 0;
  for (const w of wordsA) if (w.length > 2 && wordsB.includes(w)) common++;
  return (common / Math.max(wordsA.length, 1)) * 70;
}

const searchStr = `${identified.title} ${identified.author} ${identified.keywords}`;
let best = null, bestScore = 0;
for (const p of products) {
  const titleScore = score(searchStr, p.book_title);
  const authorScore = score(identified.author, p.author);
  const total = Math.max(titleScore, titleScore * 0.7 + authorScore * 0.3);
  if (total > bestScore) { bestScore = total; best = p; }
}

const ctx = $('Normalize Message').first().json;
let replyContext = '';
if (best && bestScore >= 40) {
  replyContext = `কাস্টমার একটি বইয়ের ছবি পাঠিয়েছে। আমরা ছবি থেকে চিনেছি: "${identified.title}" (লেখক: ${identified.author})।\nশিটে মিল পাওয়া বই:\n- নাম: ${best.book_title}\n- লেখক: ${best.author}\n- দাম: ${best.price} টাকা\n- স্টক: ${best.stock}\n- অফার: ${best.offer || 'নেই'}\n- বিবরণ: ${best.description || ''}\n\nকাস্টমারকে এই বইয়ের দাম ও তথ্য বন্ধুত্বপূর্ণভাবে জানাও এবং অর্ডার করতে আগ্রহী কিনা জিজ্ঞেস করো।`;
} else {
  replyContext = `কাস্টমার একটি বইয়ের ছবি পাঠিয়েছে কিন্তু আমাদের শিটে নিশ্চিতভাবে মিল পাওয়া যায়নি (চেনা গেছে: "${identified.title}")। কাস্টমারকে নম্রভাবে বইয়ের সঠিক নাম জিজ্ঞেস করো অথবা জানাও যে আমাদের একজন প্রতিনিধি শীঘ্রই কনফার্ম করে জানাবেন।`;
}

return [{ json: { ...ctx, identified, matchedProduct: best, matchScore: bestScore, replyContext } }];

// টেক্সট প্রশ্নের জন্য context তৈরি: product list + history
const current = $('Normalize Message').first().json;
const products = $('Read Product Sheet (for text)').all().map(r => r.json);
const stateRows = $('Get Conversation State').all().filter(r => r.json.sender_id);

let conversationHistory = [];
let orderState = {};
if (stateRows.length > 0) {
  conversationHistory = JSON.parse(stateRows[0].json.conversation_history || '[]');
  orderState = JSON.parse(stateRows[0].json.order_state || '{}');
}

// Product catalog string (token বাঁচাতে মূল ফিল্ড)
const catalog = products.map(p => `• ${p.book_title} | লেখক: ${p.author} | দাম: ${p.price}৳ | স্টক: ${p.stock} | অফার: ${p.offer || 'নেই'}`).join('\n');

conversationHistory.push({ role: 'user', content: current.messageText });
if (conversationHistory.length > 20) conversationHistory = conversationHistory.slice(-20);

return [{
  json: {
    ...current,
    catalog,
    conversationHistory,
    orderState,
    isNewConversation: stateRows.length === 0
  }
}];

// AI response parse — দুই branch (text/image) থেকেই আসতে পারে
const aiOut = $input.first().json;
const raw = aiOut.content || aiOut.text || aiOut.message?.content || '';

let clean = raw, orderData = null;
const m = raw.match(/\[ORDER_DATA:(\{[\s\S]*?\})\]/);
if (m) {
  try { orderData = JSON.parse(m[1]); clean = raw.replace(/\[ORDER_DATA:\{[\s\S]*?\}\]/, '').trim(); } catch (e) {}
}

const handoverKeywords = ['টিমকে জানাচ্ছি', 'যোগাযোগ করবেন', 'প্রতিনিধি'];
let needsHandover = handoverKeywords.some(k => clean.includes(k)) || orderData?.stage === 'handover';

// context — text হলে Build Text Context, image হলে Match Book
let ctx;
try { ctx = $('Build Text Context').first().json; }
catch (e) { ctx = $('Match Book to Sheet').first().json; }

let history = ctx.conversationHistory || [{ role: 'user', content: ctx.messageText }];

return [{ json: { ...ctx, aiResponse: clean, orderData, needsHandover, conversationHistory: history } }];

