// State আপডেটের জন্য ডেটা প্রস্তুত
const ctx = $('Parse AI Response').first().json;
const history = [...(ctx.conversationHistory || [])];
history.push({ role: 'assistant', content: ctx.aiResponse });

let orderState = ctx.orderState || {};
if (ctx.orderData) {
  orderState = { stage: ctx.orderData.stage, collected: ctx.orderData.collected || orderState.collected || {} };
}
if (ctx.orderData?.stage === 'confirmed') orderState = {};

return [{
  json: {
    sender_id: ctx.senderId,
    channel: 'whatsapp',
    phone_number_id: ctx.phoneNumberId || '',
    conversation_history: JSON.stringify(history.slice(-20)),
    order_state: JSON.stringify(orderState),
    last_contact_time: new Date().toISOString(),
    followup_sent: 'false',
    is_new: ctx.isNewConversation === true
  }
}];

// order_state is a JSON string kept in the sheet; a hand-edited or truncated cell must not
// crash the whole follow-up run, so treat anything unreadable as "no order in progress".
const safeParse = (s) => {
  try { const v = JSON.parse(s || '{}'); return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; }
  catch (e) { return {}; }
};
const now = Date.now();
const min30 = 30*60*1000, hr2 = 120*60*1000;
const out = [];
for (const row of $input.all()) {
  const r = row.json;
  if (!r.sender_id || !r.last_contact_time || r.channel !== 'whatsapp') continue;
  const since = now - new Date(r.last_contact_time).getTime();
  const sent = r.followup_sent === 'true' || r.followup_sent === true;
  const os = safeParse(r.order_state);
  const done = os.stage === 'confirmed' || !os.stage;
  if (since >= min30 && since <= hr2 && !sent && !done) {
    out.push({ json: { senderId: r.sender_id, phoneNumberId: r.phone_number_id, orderState: os } });
  }
}
return out.length ? out : [{ json: { skip: true } }];
